219:     private fun getIdForSerial(serial: String): String? {
220:         var id: String? = null
221:         val idDetectionProcess = processFactory(
222:             listOf(
223:                 adbExecutable.absolutePath,
224:                 "-s",
225:                 serial,
226:                 "emu",
227:                 "avd",
228:                 "id"
229:             )
230:         ).start()
231: 
232:         try {
233:             runWithTimeout(ADB_TIMEOUT_SEC) {
234:                 GrabProcessOutput.grabProcessOutput(
235:                     idDetectionProcess,
236:                     GrabProcessOutput.Wait.WAIT_FOR_READERS,
237:                     object : GrabProcessOutput.IProcessOutput {
238:                         override fun out(line: String?) {
239:                             line ?: return
240:                             val trimmed = line.trim()
241:                             if (trimmed.isNotEmpty() && trimmed != "OK") {
242:                                 id = trimmed
243:                             }
244:                         }
245: 
246:                         override fun err(line: String?) {}
247:                     }, null, null
248:                 )
249: 
250:                 idDetectionProcess.waitFor()
251:             }
252:         } catch (e: TimeoutException) {
253:             // If we fail to retrieve the id, simply return null. This should not be an error.
254:             idDetectionProcess.destroy()
255:             idDetectionProcess.waitFor()
256:         }
257:         return id

