30: abstract class RunUtpWorkAction @Inject constructor(
31: ): WorkAction<RunUtpWorkParameters> {
32: 
33:     private val logger = Logging.getLogger(RunUtpWorkAction::class.java)
34: 
35:     @VisibleForTesting
36:     fun processFactory(): (List<String>) -> ProcessBuilder = { ProcessBuilder(it) }
37: 
38:     override fun execute() {
39:         val processBuilder = processFactory().invoke(
40:             listOfNotNull(
41:                 parameters.jvm.asFile.get().absolutePath,
42:                 "-Djava.awt.headless=true",
43:                 "-Djava.util.logging.config.file=${
44:                     parameters.loggingProperties.asFile.get().absolutePath}",
45:                 "-Dfile.encoding=UTF-8",
46:                 "-cp",
47:                 parameters.launcherJar.joinToString(File.pathSeparator) { it.absolutePath },
48:                 UtpDependency.LAUNCHER.mainClass,
49:                 parameters.coreJar.joinToString(File.pathSeparator) { it.absolutePath },
50:                 "--proto_config=${parameters.runnerConfig.asFile.get().absolutePath}",
51:                 "--proto_server_config=${parameters.serverConfig.asFile.get().absolutePath}"
52:             )
53:         )
54:         val process = processBuilder.start()
55: 
56:         // Shutdown hook to close the process if gradle is closed/cancelled.
57:         val shutdownHook = Thread(process::destroyForcibly)
58: 
59:         try {
60:             Runtime.getRuntime().addShutdownHook(shutdownHook)
61: 
62:             GrabProcessOutput.grabProcessOutput(
63:                 process,
64:                 GrabProcessOutput.Wait.ASYNC,
65:                 object : GrabProcessOutput.IProcessOutput {
66:                     override fun out(line: String?) {
67:                         if (!line.isNullOrBlank()) {
68:                             logger.info(line)
69:                         }
70:                     }
71: 
72:                     override fun err(line: String?) {
73:                         if (!line.isNullOrBlank()) {
74:                             logger.info(line)
75:                         }
76:                     }
77:                 }, null, null
78:             )
79: 
80:             process.waitFor()
81:         } finally {
82:             Runtime.getRuntime().removeShutdownHook(shutdownHook)
83:         }
84:     }
85: }

