1640:     /**
1641:      * Returns the port where adb server should be launched. This looks at:
1642:      *
1643:      * <ol>
1644:      *   <li>The system property ANDROID_ADB_SERVER_PORT
1645:      *   <li>The environment variable ANDROID_ADB_SERVER_PORT
1646:      *   <li>Defaults to {@link #DEFAULT_ADB_PORT} if neither the system property nor the env var
1647:      *       are set.
1648:      * </ol>
1649:      *
1650:      * @return The port number where the host's adb should be expected or started.
1651:      */
1652:     private static int getAdbServerPort() {
1653:         // check system property
1654:         Integer prop = Integer.getInteger(SERVER_PORT_ENV_VAR);
1655:         if (prop != null) {
1656:             try {
1657:                 return validateAdbServerPort(prop.toString());
1658:             } catch (IllegalArgumentException e) {
1659:                 String msg =
1660:                         String.format(
1661:                                 "Invalid value (%1$s) for ANDROID_ADB_SERVER_PORT system property.",
1662:                                 prop);
1663:                 Log.w(DDMS, msg);
1664:             }
1665:         }
1666: 
1667:         // when system property is not set or is invalid, parse environment property
1668:         try {
1669:             String env = System.getenv(SERVER_PORT_ENV_VAR);
1670:             if (env != null) {
1671:                 return validateAdbServerPort(env);
1672:             }
1673:         } catch (SecurityException ex) {
1674:             // A security manager has been installed that doesn't allow access to env vars.
1675:             // So an environment variable might have been set, but we can't tell.
1676:             // Let's log a warning and continue with ADB's default port.
1677:             // The issue is that adb would be started (by the forked process having access
1678:             // to the env vars) on the desired port, but within this process, we can't figure out
1679:             // what that port is. However, a security manager not granting access to env vars
1680:             // but allowing to fork is a rare and interesting configuration, so the right
1681:             // thing seems to be to continue using the default port, as forking is likely to
1682:             // fail later on in the scenario of the security manager.
1683:             Log.w(
1684:                     DDMS,
1685:                     "No access to env variables allowed by current security manager. "
1686:                             + "If you've set ANDROID_ADB_SERVER_PORT: it's being ignored.");
1687:         } catch (IllegalArgumentException e) {
1688:             String msg =
1689:                     String.format(
1690:                             "Invalid value (%1$s) for ANDROID_ADB_SERVER_PORT environment variable"
1691:                                     + " (%2$s).",
1692:                             prop, e.getMessage());
1693:             Log.w(DDMS, msg);
1694:         }
1695: 
1696:         // use default port if neither are set
1697:         return DEFAULT_ADB_PORT;
1698:     }

